358	func (p *Parser) parsePrimary() (*ast.Node, error) {
359		switch p.curToken.Type {
360		case ast.TokenInt:
361			node := &ast.Node{
362				Kind:  ast.NodeIntLit,
363				Value: p.curToken.Value,
364				Line:  p.curToken.Line,
365				Col:   p.curToken.Col,
366			}
367			return node, nil
368	
369		case ast.TokenTrue:
370			node := &ast.Node{
371				Kind:  ast.NodeBoolLit,
372				Value: "true",
373				Line:  p.curToken.Line,
374				Col:   p.curToken.Col,
375			}
376			return node, nil
377	
378		case ast.TokenFalse:
379			node := &ast.Node{
380				Kind:  ast.NodeBoolLit,
381				Value: "false",
382				Line:  p.curToken.Line,
383				Col:   p.curToken.Col,
384			}
385			return node, nil
386	
387		case ast.TokenString:
388			node := &ast.Node{
389				Kind:  ast.NodeStringLit,
390				Value: p.curToken.Value,
391				Line:  p.curToken.Line,
392				Col:   p.curToken.Col,
393			}
394			return node, nil
395	
396		case ast.TokenIdent:
397			name := p.curToken.Value
398			node := &ast.Node{
399				Kind:  ast.NodeIdent,
400				Value: name,
401				Line:  p.curToken.Line,
402				Col:   p.curToken.Col,
403			}
404			// Check if next token is '{' for struct initialization
405			if p.peekToken.Type == ast.TokenLBrace {
406				p.nextToken() // move to '{'
407				return p.parseStructLit(name)
408			}
409			return node, nil
410	
411		case ast.TokenLParen:
412			p.nextToken()
413			expr, err := p.parseExpression(0)
414			if err != nil {
415				return nil, err
416			}
417			if p.curToken.Type != ast.TokenRParen {
418				return nil, fmt.Errorf("expected ')'")
419			}
420			return expr, nil
421	
422		case ast.TokenLBracket:
423			return p.parseArrayLit()
424	
425		case ast.TokenBang:
426			p.nextToken()
427			expr, err := p.parsePrimary()
428			if err != nil {
429				return nil, err
430			}
431			return &ast.Node{
432				Kind:     ast.NodeUnaryExpr,
433				Value:    "!",
434				Line:     p.curToken.Line,
435				Col:      p.curToken.Col,
436				Children: []*ast.Node{expr},
437			}, nil
438	
439		default:
440			return nil, fmt.Errorf("unexpected token: %v", p.curToken.Type)
441		}
442	}
