506	func (p *Parser) peekPrecedence() int {
507		return precedence(p.peekToken.Type)
508	}
509	
510	func (p *Parser) curPrecedence() int {
511		return precedence(p.curToken.Type)
512	}
513	
514	func precedence(tok ast.TokenType) int {
515		switch tok {
516		case ast.TokenOr:
517			return 0
518		case ast.TokenAnd:
519			return 1
520		case ast.TokenEq, ast.TokenNe, ast.TokenLt, ast.TokenGt, ast.TokenLe, ast.TokenGe:
521			return 1
522		case ast.TokenPlus, ast.TokenMinus:
523			return 2
524		case ast.TokenStar, ast.TokenSlash:
525			return 3
526		case ast.TokenDotDot:
527			return 4
528		case ast.TokenDot, ast.TokenLBracket:
529			return 5
530		default:
531			return 0
532		}
533	}
534	
535	func (p *Parser) skipSemicolons() {
536		for p.curToken.Type == ast.TokenSemicolon {
537			p.nextToken()
538		}
539	}
