581	func (p *Parser) parseFieldDecl() (*ast.Node, error) {
582		if p.curToken.Type != ast.TokenIdent {
583			return nil, fmt.Errorf("expected field name")
584		}
585	
586		fieldNode := &ast.Node{
587			Kind:  ast.NodeFieldDecl,
588			Value: p.curToken.Value,
589			Line:  p.curToken.Line,
590			Col:   p.curToken.Col,
591		}
592	
593		p.nextToken() // consume field name
594	
595		if p.curToken.Type != ast.TokenColon {
596			return nil, fmt.Errorf("expected ':' after field name")
597		}
598	
599		p.nextToken() // consume ':'
600	
601		if p.curToken.Type != ast.TokenIdent {
602			return nil, fmt.Errorf("expected field type")
603		}
604	
605		typeNode := &ast.Node{
606			Kind:  ast.NodeIdent,
607			Value: p.curToken.Value,
608			Line:  p.curToken.Line,
609			Col:   p.curToken.Col,
610		}
611		fieldNode.TypeAnnotation = p.curToken.Value // Store type annotation directly
612		fieldNode.Children = append(fieldNode.Children, typeNode)
613	
614		p.nextToken() // consume type
615	
616		return fieldNode, nil
617	}
